                  "trans": "燕子飞来的时候正逢新社，梨花落尽之后又到了清明。池塘边有三四点碧绿的苔痕，树叶底下传来一两声黄鹂鸣叫，白昼渐长，柳絮轻轻飞舞。东邻的女伴露出巧笑，在采桑的小路上相遇。她们猜想昨夜一定做了美好的春梦，原来只是因为今天斗草赢了，笑容从两边脸颊上自然绽放。",
