                  "trans": "边塞秋天的景色与内地不同，大雁飞往衡阳，毫不留恋这里。四面传来边地的声音，号角也接连响起。重重山岭之间，暮烟、落日笼罩着一座孤城，城门已经关闭。喝下一杯浊酒，却仍然相隔万里思念家乡。边功尚未建立，还没有归家的办法。悠长的羌笛声在满地秋霜中回荡。人们整夜不能入睡，将军已经白发，士卒也流下思乡的眼泪。",
                  "note": "创作背景：范仲淹任陕西经略副使期间，驻守西北边地。这首词写边塞秋景和戍边将士的思乡、责任与苦闷。“燕然未勒”用东汉窦宪登燕然山刻石记功的典故，说明边功未成，不能轻易归乡。\n艺术特点与历史地位：把边塞词从宴饮歌舞中拓展到军镇生活、家国责任和士卒情感；“孤城闭”“将军白发征夫泪”具有强烈的历史现场感。",
