                  "note": "创作背景：词写秋日羁旅和思乡。上阕从高天、黄叶、秋水写到芳草远方，下阕转入夜间梦、楼、酒和泪，景物由开阔转为内收。\n艺术特点与历史地位：上阕以大景写乡愁，下阕以酒泪收束；是范仲淹婉约词代表，也显示他词中兼有边塞和柔情两面。",
