                  "note": "创作背景：词写秋夜望月、怀人和孤眠。上阕由落叶寒声写到月照千里，下阕写酒未入口已化泪，表现难以排遣的相思。\n艺术特点与历史地位：上阕写外在秋夜，下阕写内在孤眠；“眉间心上”后来成为描写相思的经典语汇。",
