                  "trans": "杜鹃接连鸣叫几声，又报告春天的芳菲已经消歇。怜惜春光将尽，反而把残存的红花折下。雨势虽轻，风色却猛烈，正是梅子开始青涩的时节。永丰坊的柳树无人欣赏，整日只有花絮像雪一样纷纷飞落。不要弹那根细弦了，怨恨到了极点，连琴弦也仿佛能够替人诉说。天不会老去，深情也难以断绝。我的心像一张由双丝织成的网，里面结着千千万万的心结。夜已经过去，东窗外天还没有亮，孤灯却已经熄灭。",
