                  "trans": "薄被小枕遇上清凉的天气，忽然尝到离别的滋味。翻来覆去数着一更又一更，刚刚睡醒还想重新入睡。终究无法睡着，一整夜漫长得像一年。本来也想等一等，再回头牵马回去，可又怎奈出行的计划已经定下。千般思量，想尽各种办法排解，却始终只是寂寞无聊。我的一生心意都系在你身上，却辜负了你流下的千行眼泪。",
