                  "trans": "我久久倚靠在高楼上，细风轻轻吹来。极目远望，春日的愁绪从遥远的天边暗暗生起。草色和烟雾笼罩在夕阳余晖中，默默凭栏的心情，又有谁能够理解呢？本想放纵自己，借酒求醉；面对美酒高歌，勉强得到的快乐终究没有滋味。即使因此日渐消瘦，我也绝不后悔，为了你甘愿憔悴下去。",
