                    "草木红衰翠减，万物渐渐凋零，只有长江默默东流。",
                    "词人不忍登高远望，因为故乡遥远，归思难以收束。",
                    "他想象佳人登楼远望，把天边驶来的船误认为归舟；哪里知道自己倚栏时，也正被愁绪凝住。"
