                    "玉勒雕鞍游冶处，楼高不见章台路：外面是骑着华美马匹游乐的地方，女子登楼却看不见章台的道路。",
                    "雨横风狂三月暮：暮春风急雨骤，春天将尽。",
                    "门掩黄昏，无计留春住：黄昏关门，却没有办法把春天留住。",
                    "泪眼问花花不语，乱红飞过秋千去：含泪问花，花默默不答，只见残花被风吹过秋千。花的沉默把人的无言愁苦外化。"
