                  "trans": "平坦的岸边有一座小桥，四周被千重山峰环抱；柔和的蓝色水流环绕着花草。几间茅屋的窗户幽深雅致，尘埃无法进入，时时都有春风替它清扫。午睡醒来，听见鸟儿鸣叫，斜倚着睡意未消，仿佛听到了美好的朝阳之声。忽然想起老朋友们如今都已经老去。还是贪恋梦境的美好吧，竟茫然忘记了人生如邯郸梦般的道路。",
                  "note": "创作背景：王安石晚年居金陵时写山居闲适。词先写幽静清美的居处，再由鸟声和午梦引出对故人老去、人生如梦的感慨。\n艺术特点与历史地位：上片写理想化的山居环境，下片由闲适转入人生如梦，清丽中含有晚年哲思。"
