            {
              "label": "长调（91 字以上）",
              "works": [
                {
                  "title": "念奴娇·断虹霁雨",
                  "form": "双调",
                  "original": [
                    "断虹霁雨，净秋空，山染修眉新绿。桂影扶疏，谁便道，今夕清辉不足。万里青天，姮娥何处，驾此一轮玉。寒光零乱，为谁偏照醽醁。",
                    "年少从我追游，晚凉幽径，绕张园森木。共倒金荷，家万里，难得尊前相属。老子平生，江南江北，最爱临风笛。孙郎微笑，坐来声喷霜竹。"
                  ],
                  "trans": "雨过天晴，彩虹已经断续消失，秋天的天空澄净无尘，山色像刚刚画出的长眉一样新绿。月中桂影疏落摇曳，谁说今晚的月光还不够清亮？万里青天之上，嫦娥在哪里？她驾着这一轮白玉般的明月而来。清冷的月光零乱地照在酒杯上，它究竟偏偏为谁照亮美酒呢？\n\n年轻时我曾跟随朋友游赏，晚风清凉，我们走在幽静小径，绕过张园茂密的树木。大家共同举起荷叶形的金杯饮酒；身在万里之外，难得能在席前这样相聚。老夫一生走遍江南江北，最爱迎风听笛。想当年孙权听到笛声也会微笑，如今笛声坐间响起，仿佛从霜竹中喷薄而出。",
                  "note": "创作背景：黄庭坚在秋雨初晴、月色清朗之夜宴饮游园。词上片写月下秋景，下片回忆与友人游赏和饮酒，末以孙权爱听笛的典故写音乐与豪兴。\n艺术特点与历史地位：景物清奇，意象密集，用神话和历史典故拓展月夜宴饮的文化空间，兼有黄庭坚词的生新和豪放。",
                  "gloss": [
                    "雨后彩虹消隐，秋空澄净，山色如新画的眉黛，清丽而有层次。",
                    "“桂影扶疏”写月中桂影；“清辉不足”反衬月色之盛。",
                    "“姮娥”即嫦娥，玉轮指月亮；问她从何处驾月而来，使月色神话化。",
                    "“寒光零乱”写月光映酒，视觉景象与宴饮情境结合。",
                    "下片写年轻时相从游赏，也写身在万里之外仍能在酒席相聚的珍贵。",
                    "“临风笛”及“孙郎微笑”把个人听笛之乐提升为江南江北的文化记忆。"
                  ]
                }
              ]
            }
