                    "金风玉露一相逢，便胜却人间无数：秋风白露中的一次相逢，胜过人间无数次庸常相会。",
                    "柔情似水，佳期如梦：柔情绵长如水，美好相会却短暂如梦。",
                    "忍顾鹊桥归路：怎么忍心回头看踏上鹊桥离去的道路？",
                    "两情若是久长时，又岂在朝朝暮暮：如果两情能够长久，又何必拘泥于日日夜夜相守。"
