                  "note": "创作背景：秦观写春日清晨登小楼所见。轻寒、晓阴、淡烟、流水和细雨共同营造出朦胧幽静的氛围，结尾回到闺中闲居。\n艺术特点与历史地位：以“飞花似梦、丝雨如愁”的比喻把视觉景物转化为心理感受，是秦观婉约词中最具代表性的名篇之一。"
