                  "trans": "树木环绕着村庄，池塘里的水已经涨满。我迎着东风，兴致豪迈地自在游逛。小小的园子却收尽了整个春天的光彩：有红色的桃花、白色的李花和黄色的菜花。远处是环绕的围墙，隐约可见茅草屋舍；青色酒旗在风中飘扬，旁边还有流水和小桥。我偶然兴致一来，便走过东边的山冈。正好看见黄莺啼叫、燕子飞舞、蝴蝶忙碌。",
                  "note": "创作背景：秦观写春日乡村游赏。词不写城市楼台，而写村庄、陂塘、菜花、茅堂和农野小径，表现明丽充实的民间春景。\n艺术特点与历史地位：色彩明丽，层次丰富，以红、白、黄三色和莺、燕、蝶三种动态形象构成乡村春景，是秦观词中格调明快的代表作。"
