                  "trans": "细雨刚刚带来寒意，斜阳拨开云层，天气转晴，春意却显得空旷。长亭边的柳色刚刚变黄，远行的客人先折下一枝柳条。水边烟雾横斜，映照着几点归来的乌鸦，东风已经吹尽边地的积雪。还记得当年出关时，正好也是这样的时节。即将出发时，画楼中的美酒和红泪相伴着清歌，短暂的欢会很快就要变成离别。这样美好的夜晚和景色，却没有人可以共同诉说。想那深沉的绣阁中，谁知道远方的人已经憔悴消瘦？天涯风月清冷如钩，即使有梦可以相寻，又何处没有明月呢？",
