                    "须信鸾弦易断，奈云和再鼓，曲终人远。认罗袜无踪，旧处弄波清浅。青翰棹舣，白蘋洲畔，尽目临皋飞观。待烦纤手，卷上珠帘，笑看金钗双燕。"
