                  "trans": "讨厌黄莺的叫声传到枕边，花香又吹动帘幕，醉意和愁梦交织在一起。被子还珍惜残留的香气，衣带却惊动了残存的睡意，春天将晚，伤春之情究竟有多少？泪痕像竹上的露痕一样新鲜，佩兰的香气却已经衰老，湘江一带春天的天气浓暖。还记得小江边风月最美的时候，曾多次约她同游。怎能不相信鸾凤琴弦容易断裂？即使重新鼓奏，曲终之后人也已经远去。想寻找她的踪迹，却只见旧日水波清浅。青色画船停在白蘋洲边，极目远处是临皋高台。只等她伸手卷起珠帘，笑看金钗旁成双飞过的燕子。",
                  "note": "创作背景：贺铸写暮春怀人。莺声、花气、余香和残妆触发相思，词中又追忆湘江游赏和旧日约会，末尾以珠帘、金钗和双燕收束。\n艺术特点与历史地位：意象繁密，兼用湘水、佩兰、鸾弦等古典意象，把春晚、旧游和人远交织在一起，体现贺铸词的绵密与奇峭。"
