                  "trans": "并州的刀锋清亮如水，吴地的盐洁白胜雪，一双纤手剥开新鲜的橙子。锦帐中刚刚温暖起来，兽形香炉的烟气不断升起，两人相对坐着调弄笙声。她低声问道：你今夜要到哪里投宿？城上已经三更了，马匹容易在浓霜中打滑，不如不要离去，外面正是行人稀少的时候。",
                  "note": "创作背景：词写冬夜宴饮和劝留。并刀、吴盐、新橙、锦幄、兽烟与调笙构成精致室内空间，下阕转入夜深霜浓、劝客留宿。\n艺术特点与历史地位：从器物、动作、气味和声音写近距离室内生活，末以时间和天气劝留；是周邦彦小令代表。",
                  "gloss": [
                    "刀如水清，盐如雪白，纤手剥开橙子；帐中温暖，香烟不断，两人对坐调笙。",
                    "女子低声问客人夜里投宿何处，城上已三更，霜浓路滑，不如留下，因为外面行人很少。"
                  ]
