                  "trans": "清晨的云雾淡淡散开，像轻丝一样飘动，楼阁笼罩着朦胧的春色。柳枝仿佛含泪，花朵仿佛啼泣，城中街道泥泞深重，门外燕子飞得迟缓。如今阳光明亮，照着华美的楼屋，桃枝上的春色也正盛。可是这一切都不像当年，两个人一起冒雨走过小桥，那种幽微的愁恨只有彼此知道。",
