                  "trans": "天上的银河正在转动，人间的帘幕已经低垂。凉意从枕席间生起，泪痕不断增加；我起身解下衣服，姑且问一问，夜已经深到什么时候了。翠色的荷叶贴着小小的莲蓬，金色的荷花已经稀疏。天气还是从前的天气，衣服也还是从前的衣服，只有我的心情已经不像过去在故乡时那样了。",
