                  "form": "双调",
                  "original": [
                    "裁剪冰绡，轻叠数重，淡著燕脂匀注。新样靓妆，艳溢香融，羞杀蕊珠宫女。易得凋零，更多少、无情风雨。愁苦。问院落凄凉，几番春暮。",
                    "凭寄离恨重重，者双燕何曾，会人言语。天遥地远，万水千山，知他故宫何处。怎不思量，除梦里、有时曾去。无据。和梦也新来不做。"
                  ],
                  "trans": "杏花像用冰雪般的丝绸裁剪而成，又轻轻叠了几层，淡淡染上胭脂，均匀地点缀。它刚换上新式的美丽妆容，艳色和香气交融，连仙宫中的花蕊宫女也要羞惭。可是花朵容易凋零，更经不起无情的风雨。真令人愁苦。试问这凄凉的庭院，已经经历了多少次春天将尽？我只能寄托重重离恨，然而这双燕子又怎么能够听懂人的话语？天地遥远，山水万重，它知道故宫究竟在什么地方吗？怎么能够不去思量呢？只有在梦中，偶尔还曾回到那里。可是如今连梦也没有凭据，近来竟连梦都做不成了。",
