                  "trans": "回忆从前在午桥桥上饮酒，座中大多是豪迈英俊的人物。长沟中的月影无声无息地流去。在稀疏的杏花影子里，我们吹笛一直到天明。二十多年转眼如同一场梦，我这个人虽然还活着，却也不免为经历的一切震惊。闲来登上小阁，观看雨后初晴。古往今来有多少兴亡往事，都伴随着三更时分渔人的歌声传来。",
                  "note": "创作背景：陈与义南渡后追忆洛阳旧游。上片写昔日与友人饮酒、赏月、听笛的青春盛会；下片写战乱和漂泊之后的自伤及对历史的沉思。\n艺术特点与历史地位：以“忆昔—伤今—思古”的结构，把个人身世、北宋旧游和南渡后的历史感交织起来；末句含蓄深沉，具有南宋词的时代气息。",
