                  "trans": "高声吟诵楚辞，来酬答端午节日，可是人在天涯，节令匆匆过去。石榴花的红色也比不上舞女衣裙的鲜艳。没有人知道我此刻的心意，歌唱完毕，只剩满帘清风。世间万事都压在一身之上，令人感伤自己已经老了。墙东的向日葵仿佛还在含笑。酒杯的深浅和去年相同。试着把酒洒入桥下的流水，希望今晚它能够流到湘江，寄托我对屈原和故国的追怀。",
