                  "title": "水调歌头·秋色渐将晚",
                  "form": "双调",
                  "original": [
                    "秋色渐将晚，霜信报黄花。小窗低户深映，微路绕欹斜。为问山翁何事，坐看流年轻度，拚却鬓双华。徙倚望沧海，天净水明霞。",
                    "念平昔，空飘荡，遍天涯。归来三径重扫，松竹本吾家。却恨悲风时起，冉冉云间新雁，边马怨胡笳。谁似东山老，谈笑静胡沙。"
                  ],
                  "trans": "秋意渐渐深了，霜降的消息由菊花传来。低矮的小窗和门户掩映在深处，弯曲的小路环绕着倾斜的景物。试问山中的老人有什么事情？不过是坐看流水般的年华轻轻过去，任凭两鬓添上白发。我徘徊着眺望大海，只见天空澄净，水面映着明亮的霞光。\n\n回想往日，自己徒然漂泊，走遍天涯。如今归来，重新打扫门前小径，松树和竹子本来就是我的家。只是遗憾悲风不时吹起，云间新雁缓缓飞过，边地战马的嘶鸣仿佛伴着胡笳传来。谁能像东山高士谢安那样，在谈笑之间平定边疆呢？",
