                    "回想多年在岭外，孤月照着自己，内心如冰雪般清白。",
                    "头发稀疏、衣襟生寒，却安稳漂荡在开阔水面。",
                    "仿佛舀尽西江、斟满北斗，把天地万物都请作宾客；扣舷长啸，忘记今夕何夕。"
