                  "trans": "梅花开在驿站外的断桥边，孤独地开放，没有人照料。黄昏时已经独自忧愁，又遭受风吹雨打。它无意苦苦争夺春光，任凭百花嫉妒。即使凋零后被碾成泥、化作尘土，香气仍然和从前一样。",
                  "note": "创作背景：陆游一生以恢复中原为志，屡遭主和派排挤。词借梅花处境写孤高不屈，但具体作年和所指人物不宜过度坐实。下阕“香如故”使梅花具有品格象征意义。\n艺术特点与历史地位：全词不直接议论人格，而用梅花的环境、选择和结局完成象征；“香如故”成为后世表达坚守品格的经典意象。",
                  "gloss": [
                    "驿外断桥边，寂寞开无主：梅花开在驿站外的断桥边，孤独而无人照料。",
                    "已是黄昏独自愁，更著风和雨：黄昏时已独自忧愁，又遭风雨摧打，处境更加艰难。",
                    "无意苦争春，一任群芳妒：它无意与百花争春，任凭群花嫉妒，表现不求争宠的态度。",
                    "零落成泥碾作尘，只有香如故：即使凋零成泥、被车轮碾成尘土，香气仍和原来一样，写人格操守不改。"
                  ]
