                  "trans": "当年在华灯照耀下纵情赌博，骑着雕鞍骏马驰骋射猎，又有谁还记得那时的豪迈举动？当年的酒友中已有一半获得封侯，只有我独自离去，做了江边的渔父。一叶八尺轻舟，配着三扇低低的船篷，占尽蘋洲上的烟雨风光。镜湖本来就属于闲适之人，哪里还需要皇帝特意赐给我呢？",
                  "note": "创作背景：陆游晚年退居山阴，追忆年轻时的豪情和军旅志向。如今只能驾轻舟、居江湖，但词中仍有不甘被闲置的傲岸和自尊。\n艺术特点与历史地位：上片追忆豪游和功名，下片转写退居江湖，以轻快口吻掩住报国无门的复杂心情，体现陆游闲居词中的不平与旷达。"
