                  "trans": "想起当年带着羽箭雕弓，在古老营垒间呼鹰，在平坦原野上截击猛虎；傍晚吹着胡笳回到野外军帐，大雪压在青毡之上。醉后挥毫，墨迹淋漓，仿佛龙蛇飞落在纸笺上。人们曾经误以为，我在诗情和军事谋略上都一时超群。如今为什么又来到南方？看重阳节的药市和元宵夜的灯山。花开时节万人同乐的地方，我斜戴帽子、垂着马鞭经过。听见歌声便感念旧事，还常常在酒席前流泪。请你记住，封侯立功的事业还在，功名绝不只是由上天安排。",
