                  "trans": "芦苇叶子铺满了水洲，寒冷的沙滩旁带着浅浅的流水。二十年后我重新经过南楼，柳树下的船还没有系稳，再过几天，就又是中秋了。黄鹤矶头的旧址已经残断，从前的故人如今还在不在呢？过去的江山都还在，却全都变成了新的愁绪。本想买些桂花，和美酒一同装上船，可如今终究已经不像年轻时那样游赏了。",
                  "note": "创作背景：词写重过南楼和中秋将近。二十年时间、黄鹤断矶、故人不在、旧江山新愁构成南宋中后期的身世感。\n艺术特点与历史地位：用“二十年”“又中秋”“不似少年游”写时间变化，旧江山与新愁构成强烈反差。",
