                  "trans": "万匹战马没有嘶鸣，只有一声寒冷的号角传来，军令便在柳营中执行。你看这二百里山河如此险固，可惜朝廷深居万里之外，六军始终没有出发。边关之外究竟还有谁能够担当？回头看去，仿佛铁骑千群已经把敌人全部消灭。即使倚着长亭，听梅花三弄，也不必让泪水沾湿手巾。等到来年长安春早，我想那些骏马一定会追风奔驰。只是不知什么时候，朝廷能像燕昭王筑黄金台那样急切招贤？姑且让长虹贯日般的壮志冲天而起，不要让宝剑蒙尘封闭。壮士还没有老，雄心也没有止息，我愿和上天比一比高低。",
