                    "白云天竺去来。图画里、峥嵘楼阁开。爱纵横万象，平吞八极，揽将奇胜，付与诗材。雪曲高吟，玉壶争写，欲判鹅毛点黛梅。还知否，笑东坡紧指，北客难陪。"
