                  "trans": "喝着斗酒，吃着猪肩肉，在风雨中渡江，难道不是一件痛快的事吗？白居易、林逋和苏轼这些高士仿佛约我回到西湖。苏轼说，西湖正像美人西施，浓妆淡抹都对着镜台好看。可这几位高士都只是摇摇头不理会，专心举杯饮酒。白云从天竺山来去，画图般的景色中楼阁峥嵘。我喜爱这里纵横无尽的万象，仿佛平吞八方，把奇异美景都拿来作为写诗的材料。高声吟唱雪曲，用玉壶盛酒，争着写下鹅毛点染梅花般的诗句。你知道吗？苏轼还会笑着指向我，说北方来的客人难以陪伴这样的兴致。",
                  "note": "创作背景：词寄辛弃疾，写风雨渡江、西湖、苏轼、白居易和林逋等文化人物。作品有戏谑和唱和意味，也表现南宋文人对西湖文化传统的继承。\n艺术特点与历史地位：以文人典故和西湖山水组成戏剧化唱和，语言豪放而诙谐。",
