                  "trans": "春日的光景来去太急，三月转眼就要结束。我本想设法挽留，却一点办法也没有，只看见绿野中烟雾含愁，露水仿佛在哭泣。请谁替我把话带给春夜？城头的画鼓正在轻轻敲响。临近分别时，我依依不舍地叮嘱春天：明年一定要早些来到梅花梢头。",
                  "note": "创作背景：朱淑真写三月将尽时的惜春。春光迅速流逝，词人想挽留却无计可施，只能嘱咐春天来年早些回到梅梢。\n艺术特点与历史地位：把惜春写成与春天的告别，以拟人和临歧嘱咐形成亲切而哀婉的语气，体现朱淑真词中敏锐的时间意识。"
