                  "trans": "梦中那人像燕子一样轻盈，像黄莺一样娇软，分明又在华胥国的梦境中相见。漫漫长夜，怎能让薄情的人知道我的心事？春天刚刚开始，我已经被相思染透。分别以后留下的书信，分别时做的针线，都还在身边；可我的离魂却暗暗随着远行的人走远了。淮南的明月清冷地照着千山，幽暗的归魂又有谁来照料呢？",
                  "note": "创作背景：词写梦中重见旧人和别后相思。燕燕、莺莺既是轻盈形象，也可能承接旧日人物称呼；下阕以离魂随郎远行、淮南冷月写梦醒后的孤独。\n艺术特点与历史地位：由梦中人物转入书信、针线和离魂，最后扩大到淮南千山；是姜夔怀人词的名篇。",
