                  "trans": "月亮将要落下时，人还绕着湘江水边行走；横斜的小小花树浸在带愁的水波中。一整个春天的幽微心事又有谁知道呢？东风寒冷，梅花的香气远远送着穿茜色裙子的人归去。清晨鸥鸟和鹭鸟飞来窥看梅花，它们最早探知春天到来的地方。可是隔着江水，仍然有人唱着亡国的《后庭花》。只怕梨花般的云气清冷，连梦也冷得无法飞行。",
