                  "title": "琵琶仙·双桨来时",
                  "form": "双调",
                  "original": [
                    "〔序〕吴都赋云：户藏烟浦，家具画船。唯吴兴为然。春游之盛，西湖未能过也。己酉岁，予与萧时父载酒南郭，感遇成歌。",
                    "双桨来时，有人似、旧曲桃根桃叶。歌扇轻约飞花，娉婷小苑。奈雨覆云翻，雾迷烟渚。系我扁舟，个中情绪。欲语还休。",
                    "再来应为，断桥边、笼晴丝钓艇。想见西出阳关，故人初别。认得旧时鸥鹭，重过月明里。暂泊还移，莫向津头问。"
                  ],
                  "trans": "吴地的赋文说，这里家家靠近烟雾笼罩的水浦，户户都有画船。吴兴尤其如此，春日游赏的盛况甚至胜过西湖。己酉年，我和萧时父载酒到南郭游玩，因触景生情写成此词。两只船桨划来时，仿佛有人唱着旧日桃根桃叶的曲子。歌扇轻轻拂过飞花，女子在小园中姿态娉婷。无奈雨来云翻，雾气迷住烟渚，我把小舟系在这里，心中充满复杂情绪，想说却又停住。等到再来时，大概会在断桥边看晴丝笼罩钓艇。想来那时故人已经向西出了阳关，正是初次分别的时候。我还能认出从前的鸥鹭，在月明中重新经过。船暂时停泊又将移动，请不要在渡口问我什么。",
                  "note": "创作背景：词序交代吴兴春游和与友人载酒南郭。正文写旧曲、桃根桃叶、雨雾、断桥、钓艇和故人初别，具有江南水乡和送别记忆。\n艺术特点与历史地位：序文与词正文互相解释，江南水乡景物成为记忆和离别的载体；是姜夔长调代表。",
                  "gloss": [
                    "双桨来时仿佛有人唱旧曲，飞花与歌扇相伴；雨雾翻覆，扁舟系在水中，情绪欲语还休。",
                    "设想再来时断桥晴丝、故人西出阳关，只能认得旧日鸥鹭，停舟又移舟，不愿追问渡口。"
                  ]
