                  "note": "创作背景：词写梦中旧游、夕阳归燕和春暮之夜。吴文英把花、燕、落絮、行云和月都染上怀旧情绪。\n艺术特点与历史地位：物象都被赋予人的情绪，形成吴文英典型的密丽和梦幻氛围。",
