                  "trans": "听着风声和雨声度过清明，我忧愁地写下埋葬落花的文字。楼前柳色浓暗，正是当年分别的道路；一丝柳枝，牵动一寸柔情。春寒料峭，我在酒意中取暖，清晨的梦里又听见黄莺啼叫。西园里我天天打扫林亭，仍然独自欣赏雨后的新晴。黄蜂不断扑向秋千的绳索，仿佛还留着当年纤纤玉手的香气。令人惆怅的是，成双的鸳鸯再也没有来，幽暗的台阶一夜之间长满了苔藓。",
