                  "trans": "四面空旷的烟雾迷蒙，不知道是哪一年，青天坠落了一颗长星。苍翠山崖和云中树木之间，仿佛又出现了美女居住的金屋和吴王残破的宫城。箭径上的酸冷秋风直射眼睛，带着脂粉气的水把花朵染得仿佛带腥。偶尔踩着双鸳纹鞋走过，长廊边的树叶传来秋声。宫中的吴王曾经沉醉，如今只剩五湖上的倦客独自垂钓，清醒地面对一切。向苍茫水波询问却没有回答，只有白发面对青山。水面涵容天空，我站在高高的栏杆处，看乱鸦和斜阳落在渔汀。接连呼唤取酒，登上琴台去，让秋色与云层相平。",
