                  "form": "双调",
                  "original": [
                    "国脉微如缕。问长缨、何时入手，缚将戎主？未必人间无好汉，谁与宽些尺度？试看取、当年韩五。岂有谷城公付授，也不干、曾遇骊山母。谈笑起，两河路。",
                    "少时棋柝曾联句。叹而今、登楼揽镜，事机频误。闻说北风吹面急，边上冲梯屡舞。君莫道、投鞭虚语。自古一贤能制国，况更有、诸贤夹辅。听匣底，青龙吼。"
                  ],
                  "trans": "国家的命脉细弱得像一根丝线。请问束敌的长绳什么时候才能拿到手，把敌国君主捆来？人世间未必没有好汉，只是谁愿意给他们更宽的施展尺度呢？看看当年的韩五郎韩世忠就知道了。难道功业都必须靠谷城公传授，也必须遇到骊山老母指点吗？只要谈笑之间，就能重新打通两河道路。年轻时还曾与友人联句谈兵，如今却只能登楼揽镜，感叹机会一再错失。听说北风猛烈吹来，边地攻城器械频频发动。不要说投鞭断流只是空话。自古一个贤人就能安定国家，何况还有众多贤臣辅佐。听啊，剑匣里的青龙宝剑正在长鸣。",
